export function up(db) {
  db.exec(`CREATE TABLE attachments (
    id TEXT PRIMARY KEY,
    project_id TEXT NOT NULL,
    issue_id TEXT NOT NULL,
    name TEXT NOT NULL,
    media_type TEXT NOT NULL,
    size INTEGER NOT NULL CHECK(size>=0),
    sha256 TEXT NOT NULL,
    created_by TEXT NOT NULL REFERENCES users(id),
    created_at TEXT NOT NULL
  );
  CREATE INDEX attachments_issue ON attachments(issue_id,created_at,id);
  CREATE INDEX attachments_project ON attachments(project_id);`);
}

import { mkdir, open, rename, rm } from 'node:fs/promises';
import { createReadStream } from 'node:fs';
import { createHash } from 'node:crypto';
import path from 'node:path';
import { AppError, validation, text } from '@crew/shared';
export function attachmentName(value) {
  const name = text(value, 'name', { max: 255 });
  if (name === '.' || name === '..' || /[\/\\\x00-\x1f\x7f]/.test(name)) throw validation({ name: 'Use a plain file name without directory separators or control characters' });
  return name;
}
export function expectedHash(value) {
  if (value == null) return null;
  if (typeof value !== 'string' || !/^[a-f0-9]{64}$/i.test(value)) throw validation({ sha256: 'Expected a SHA-256 hex digest' });
  return value.toLowerCase();
}
export function blobPath(config, id) {
  if (!/^[a-zA-Z0-9-]+$/.test(id)) throw new AppError('BAD_REQUEST', 'Invalid attachment identifier', 400);
  return path.join(config.dataDir, 'attachments', id + '.blob');
}
export async function receiveAttachment(req, config, id, hashExpectation) {
  const declared = req.get('content-length');
  if (declared !== undefined && (!/^\d+$/.test(declared) || !Number.isSafeInteger(Number(declared)))) throw validation({ size: 'Invalid Content-Length' });
  if (declared !== undefined && Number(declared) > config.maxUploadBytes) throw new AppError('TOO_LARGE', 'Attachment exceeds the configured upload limit', 413, { maxBytes: config.maxUploadBytes });
  const target = blobPath(config, id), temporary = target + '.upload';
  await mkdir(path.dirname(target), { recursive: true, mode: 0o700 });
  const file = await open(temporary, 'wx', 0o600);
  const hash = createHash('sha256');
  let size = 0;
  let closed = false;
  try {
    for await (const bytes of req.iterator({ destroyOnReturn: false })) {
      const chunk = Buffer.isBuffer(bytes) ? bytes : Buffer.from(bytes);
      size += chunk.length;
      if (size > config.maxUploadBytes) throw new AppError('TOO_LARGE', 'Attachment exceeds the configured upload limit', 413, { maxBytes: config.maxUploadBytes });
      hash.update(chunk);
      let offset = 0;
      while (offset < chunk.length) {
        const result = await file.write(chunk, offset, chunk.length - offset);
        if (!result.bytesWritten) throw new Error('Attachment file write made no progress');
        offset += result.bytesWritten;
      }
    }
    if (req.aborted) throw new AppError('BAD_REQUEST', 'Upload was interrupted', 400);
    if (declared !== undefined && Number(declared) !== size) throw validation({ size: 'Upload length did not match Content-Length' });
    const sha256 = hash.digest('hex');
    if (hashExpectation && sha256 !== hashExpectation) throw validation({ sha256: 'Upload bytes do not match the expected SHA-256' });
    await file.close(); closed = true;
    await rename(temporary, target);
    return { size, sha256, target };
  } catch (error) {
    req.resume();
    if (!closed) await file.close();
    await rm(temporary, { force: true });
    throw error;
  }
}
export function attachmentStream(config, id) {
  return createReadStream(blobPath(config, id));
}

import { rm, access } from 'node:fs/promises';
import { rmSync } from 'node:fs';
import { pipeline } from 'node:stream/promises';
import { AppError } from '@crew/shared';
import { getIssue, validateIssueReferences } from './issues.js';
import { attachmentName, expectedHash, blobPath, receiveAttachment, attachmentStream } from './attachment-storage.js';
export function publicAttachment(row) {
  return { id: row.id, projectId: row.project_id, issueId: row.issue_id, name: row.name,
    mediaType: row.media_type, size: row.size, sha256: row.sha256, createdBy: row.created_by, createdAt: row.created_at,
    downloadUrl: '/api/v1/attachments/' + row.id + '/download' };
}
export function registerAttachments(ctx) {
  const { app, db, requireAuth, permissions, asyncRoute } = ctx;
  function issue(req, permission = 'project:read') {
    const value = getIssue(ctx, req.params.issueId);
    permissions.assertProject(req, value.projectId, permission);
    return value;
  }
  function attachment(req, permission = 'project:read') {
    const row = db.prepare('SELECT * FROM attachments WHERE id=?').get(req.params.attachmentId);
    if (!row) throw new AppError('NOT_FOUND', 'Attachment not found', 404);
    permissions.assertProject(req, row.project_id, permission);
    return row;
  }
  function emit(actorId, orgId, row, action) {
    const value = publicAttachment(row);
    ctx.bus.emit({ actorId, orgId, projectId: row.project_id, entityType: 'attachment', entityId: row.id,
      action, before: action === 'deleted' ? value : null, after: action === 'created' ? value : null, time: ctx.now() });
  }
  app.get('/api/v1/issues/:issueId/attachments', requireAuth, (req, res) => {
    const value = issue(req);
    const rows = db.prepare('SELECT * FROM attachments WHERE issue_id=? ORDER BY created_at,id').all(value.id);
    res.json({ ...ctx.paginate(rows.map(publicAttachment), req.query), maxUploadBytes: ctx.config.maxUploadBytes });
  });
  app.post('/api/v1/issues/:issueId/attachments', requireAuth, asyncRoute(async (req, res) => {
    const value = issue(req, 'attachment:write'); validateIssueReferences(ctx, value.projectId, {});
    const name = attachmentName(req.query.name ?? req.get('x-file-name'));
    const shaExpectation = expectedHash(req.get('x-content-sha256'));
    const mediaType = String(req.get('content-type') ?? 'application/octet-stream').slice(0, 255);
    if (mediaType.includes('application/json')) throw new AppError('VALIDATION', 'Send raw attachment bytes with application/octet-stream', 422, { contentType: 'JSON bodies are not attachment streams' });
    const id = ctx.id();
    const stored = await receiveAttachment(req, ctx.config, id, shaExpectation);
    let row;
    try {
      validateIssueReferences(ctx, value.projectId, {});
      getIssue(ctx, value.id);
      const time = ctx.now();
      db.prepare('INSERT INTO attachments VALUES (?,?,?,?,?,?,?,?,?)').run(id, value.projectId, value.id, name, mediaType, stored.size, stored.sha256, req.user.id, time);
      row = db.prepare('SELECT * FROM attachments WHERE id=?').get(id);
    } catch (error) { await rm(stored.target, { force: true }); throw error; }
    emit(req.user.id, value.orgId, row, 'created');
    res.status(201).json({ attachment: publicAttachment(row) });
  }));
  app.get('/api/v1/attachments/:attachmentId', requireAuth, (req, res) => res.json({ attachment: publicAttachment(attachment(req)) }));
  app.get('/api/v1/attachments/:attachmentId/download', requireAuth, asyncRoute(async (req, res) => {
    const row = attachment(req);
    try { await access(blobPath(ctx.config, row.id)); }
    catch (error) { if (error.code === 'ENOENT') throw new AppError('NOT_FOUND', 'Attachment bytes are unavailable', 404); throw error; }
    res.set({ 'Content-Type': 'application/octet-stream', 'Content-Length': String(row.size),
      'Content-Disposition': "attachment; filename*=UTF-8''" + encodeURIComponent(row.name),
      'X-Content-SHA256': row.sha256, ETag: '"sha256-' + row.sha256 + '"', 'Cache-Control': 'private, no-store' });
    await pipeline(attachmentStream(ctx.config, row.id), res);
  }));
  app.delete('/api/v1/attachments/:attachmentId', requireAuth, asyncRoute(async (req, res) => {
    const row = attachment(req, 'attachment:write');
    const project = permissions.assertProject(req, row.project_id, 'attachment:write');
    validateIssueReferences(ctx, project.id, {});
    await rm(blobPath(ctx.config, row.id), { force: true });
    db.prepare('DELETE FROM attachments WHERE id=?').run(row.id);
    emit(req.user.id, project.org_id, row, 'deleted'); res.json({ ok: true });
  }));
  const unsubscribe = ctx.bus.subscribe(event => {
    if (event.action !== 'deleted' || !['issue', 'project'].includes(event.entityType)) return;
    const column = event.entityType === 'issue' ? 'issue_id' : 'project_id';
    const rows = db.prepare('SELECT * FROM attachments WHERE ' + column + '=?').all(event.entityId);
    for (const row of rows) {
      rmSync(blobPath(ctx.config, row.id), { force: true });
      db.prepare('DELETE FROM attachments WHERE id=?').run(row.id);
      emit(event.actorId, event.orgId, row, 'deleted');
    }
  });
  (ctx.cleanups ??= []).push(unsubscribe);
}

import { registerProjects } from './projects.js';
import { registerBoards } from './boards.js';
import { registerSprints } from './sprints.js';
import { registerAttachments } from './attachments.js';
import { registerIssueRoutes } from './issue-routes.js';
export function registerRoutes(ctx) {
  registerProjects(ctx);
  registerIssueRoutes(ctx);
  registerBoards(ctx);
  registerSprints(ctx);
  registerAttachments(ctx);
}

import { AppError } from '@crew/shared';
import { getIssue } from './issues.js';
export function sprintRow(ctx, id) {
  const row = ctx.db.prepare('SELECT s.*,p.org_id FROM sprints s JOIN projects p ON p.id=s.project_id WHERE s.id=?').get(id);
  if (!row) throw new AppError('NOT_FOUND', 'Sprint not found', 404);
  return row;
}
export function getSprint(ctx, id) {
  const row = sprintRow(ctx, id);
  const totals = ctx.db.prepare(`SELECT COUNT(*) AS count,COALESCE(SUM(estimate),0) AS scope,
    COALESCE(SUM(remaining),0) AS remaining,COALESCE(SUM(1-done),0) AS unfinished
    FROM sprint_issues WHERE sprint_id=? AND active=1`).get(id);
  return {
    id: row.id, projectId: row.project_id, orgId: row.org_id, name: row.name, goal: row.goal,
    startDate: row.start_date, endDate: row.end_date, status: row.status,
    startedAt: row.started_at, completedAt: row.completed_at, createdBy: row.created_by,
    createdAt: row.created_at, updatedAt: row.updated_at,
    issueCount: totals.count, remainingIssueCount: totals.unfinished,
    scopePoints: totals.scope, remainingPoints: totals.remaining,
    result: row.result_json ? JSON.parse(row.result_json) : null
  };
}
export function sprintScope(ctx, id, { history = false } = {}) {
  return ctx.db.prepare('SELECT * FROM sprint_issues WHERE sprint_id=?' + (history ? '' : ' AND active=1') + ' ORDER BY added_at,issue_id').all(id).map(row => {
    let issue = null;
    if (ctx.db.prepare('SELECT 1 FROM issues WHERE id=?').get(row.issue_id)) issue = getIssue(ctx, row.issue_id);
    return {
      issueId: row.issue_id, active: Boolean(row.active), estimate: row.estimate,
      remaining: row.remaining, done: Boolean(row.done), title: row.title, key: row.issue_key,
      addedAt: row.added_at, removedAt: row.removed_at, issue
    };
  });
}
export function recordSprintChange(ctx, sprintId, issueId, kind, delta, at = ctx.now()) {
  ctx.db.prepare('INSERT INTO sprint_changes VALUES (?,?,?,?,?,?,?,?,?)').run(
    ctx.id(), sprintId, issueId, kind, at,
    delta.scope ?? 0, delta.remaining ?? 0, delta.issues ?? 0, delta.unfinished ?? 0
  );
}
export function addSprintIssue(ctx, sprintId, issue, at = ctx.now()) {
  const estimate = issue.estimate ?? 0;
  const done = issue.statusCategory === 'done';
  const remaining = done ? 0 : estimate;
  ctx.db.prepare(`INSERT INTO sprint_issues
    (sprint_id,issue_id,active,estimate,remaining,done,title,issue_key,added_at,removed_at)
    VALUES (?,?,1,?,?,?,?,?,?,NULL)
    ON CONFLICT(sprint_id,issue_id) DO UPDATE SET active=1,estimate=excluded.estimate,
    remaining=excluded.remaining,done=excluded.done,title=excluded.title,issue_key=excluded.issue_key,
    added_at=excluded.added_at,removed_at=NULL`).run(sprintId, issue.id, estimate, remaining, Number(done), issue.title, issue.key, at);
  recordSprintChange(ctx, sprintId, issue.id, 'added', { scope: estimate, remaining, issues: 1, unfinished: done ? 0 : 1 }, at);
}
export function removeSprintIssue(ctx, sprintId, issueId, kind = 'removed', at = ctx.now()) {
  const row = ctx.db.prepare('SELECT * FROM sprint_issues WHERE sprint_id=? AND issue_id=? AND active=1').get(sprintId, issueId);
  if (!row) throw new AppError('NOT_FOUND', 'Issue is not in this sprint', 404);
  ctx.db.prepare('UPDATE sprint_issues SET active=0,removed_at=? WHERE sprint_id=? AND issue_id=?').run(at, sprintId, issueId);
  recordSprintChange(ctx, sprintId, issueId, kind, { scope: -row.estimate, remaining: -row.remaining, issues: -1, unfinished: row.done ? 0 : -1 }, at);
}
export function getBurndown(ctx, id) {
  const sprint = getSprint(ctx, id);
  const changes = ctx.db.prepare('SELECT * FROM sprint_changes WHERE sprint_id=? ORDER BY at,id').all(id);
  const today = ctx.now().slice(0, 10);
  const finish = sprint.completedAt?.slice(0, 10) ?? today;
  const end = finish > sprint.endDate && sprint.status !== 'planned' ? finish : sprint.endDate;
  const startTime = Date.parse(sprint.startDate + 'T00:00:00.000Z');
  const daysCount = Math.round((Date.parse(end + 'T00:00:00.000Z') - startTime) / 86400000) + 1;
  const plannedDays = Math.max(1, Math.round((Date.parse(sprint.endDate) - Date.parse(sprint.startDate)) / 86400000));
  let scope = 0, remaining = 0, count = 0, unfinished = 0, cursor = 0;
  const baseline = changes.filter(change => change.at.slice(0, 10) <= sprint.startDate).reduce((sum, change) => sum + change.scope_delta, 0);
  const days = [];
  for (let index = 0; index < daysCount; index += 1) {
    const date = new Date(startTime + index * 86400000).toISOString().slice(0, 10);
    while (cursor < changes.length && changes[cursor].at.slice(0, 10) <= date) {
      const change = changes[cursor++];
      scope += change.scope_delta; remaining += change.remaining_delta;
      count += change.issue_delta; unfinished += change.remaining_issue_delta;
    }
    const future = date > today;
    days.push({
      date, scope: Math.max(0, scope), remaining: future ? null : Math.max(0, remaining),
      scopeIssues: Math.max(0, count), remainingIssues: future ? null : Math.max(0, unfinished),
      idealRemaining: Math.max(0, baseline * (1 - index / plannedDays)), future
    });
  }
  return { sprint, unit: 'points', days, changes: changes.length };
}
export function observeSprintIssues(ctx) {
  return ctx.bus.subscribe(event => {
    if (event.entityType !== 'issue') return;
    const snapshots = ctx.db.prepare(`SELECT si.* FROM sprint_issues si JOIN sprints s ON s.id=si.sprint_id
      WHERE si.issue_id=? AND si.active=1 AND s.status IN ('planned','active')`).all(event.entityId);
    for (const snapshot of snapshots) {
      const before = getSprint(ctx, snapshot.sprint_id);
      ctx.transaction(() => {
        if (!event.after) removeSprintIssue(ctx, snapshot.sprint_id, event.entityId, 'issue_deleted', event.time);
        else {
          const issue = event.after;
          const estimate = issue.estimate ?? 0;
          const done = issue.statusCategory === 'done';
          const remaining = done ? 0 : estimate;
          const changed = estimate !== snapshot.estimate || remaining !== snapshot.remaining || Number(done) !== snapshot.done;
          ctx.db.prepare('UPDATE sprint_issues SET estimate=?,remaining=?,done=?,title=?,issue_key=? WHERE sprint_id=? AND issue_id=?')
            .run(estimate, remaining, Number(done), issue.title, issue.key, snapshot.sprint_id, issue.id);
          if (changed) recordSprintChange(ctx, snapshot.sprint_id, issue.id, 'issue_changed', {
            scope: estimate - snapshot.estimate, remaining: remaining - snapshot.remaining,
            unfinished: Number(!done) - Number(!snapshot.done)
          }, event.time);
        }
      });
      ctx.bus.emit({ actorId: event.actorId, orgId: event.orgId, projectId: event.projectId,
        entityType: 'sprint', entityId: snapshot.sprint_id, action: 'issue_changed',
        before, after: getSprint(ctx, snapshot.sprint_id), time: event.time });
    }
  });
}

import { AppError, fields, text, uniqueIds, validation } from '@crew/shared';
import { sprintInput, validateSprintDates, sprintState } from '../../../../shared/src/schemas/sprint.js';
import { getIssue } from './issues.js';
import { sprintRow, getSprint, sprintScope, getBurndown, addSprintIssue, removeSprintIssue, observeSprintIssues } from './sprint-history.js';
export { getSprint, getBurndown } from './sprint-history.js';
export function registerSprints(ctx) {
  const { app, db, requireAuth, permissions } = ctx;
  function permitted(req, id, permission = 'project:read') {
    const row = sprintRow(ctx, id);
    const project = permissions.assertProject(req, row.project_id, permission);
    if (permission !== 'project:read' && project.archived) throw new AppError('CONFLICT', 'Archived projects are read-only', 409);
    return row;
  }
  function mutable(row) {
    if (row.status === 'completed') throw new AppError('CONFLICT', 'A completed sprint is historical and cannot be edited', 409);
  }
  function emit(req, row, action, before, after) {
    ctx.bus.emit({ actorId: req.user.id, orgId: row.org_id, projectId: row.project_id,
      entityType: 'sprint', entityId: row.id, action, before: before ?? null, after: after ?? null, time: ctx.now() });
  }
  function availableIssues(sprint, issueIds) {
    return issueIds.map(id => {
      const issue = getIssue(ctx, id);
      if (issue.projectId !== sprint.project_id) throw validation({ issueIds: 'Every issue must belong to the sprint project' });
      const conflict = db.prepare(`SELECT s.name FROM sprint_issues si JOIN sprints s ON s.id=si.sprint_id
        WHERE si.issue_id=? AND si.active=1 AND s.status<>'completed' AND s.id<>?`).get(id, sprint.id);
      if (conflict) throw new AppError('CONFLICT', 'Issue is already assigned to ' + conflict.name, 409, { issueId: id });
      if (db.prepare('SELECT 1 FROM sprint_issues WHERE sprint_id=? AND issue_id=? AND active=1').get(sprint.id, id)) {
        throw new AppError('CONFLICT', 'Issue is already in this sprint', 409, { issueId: id });
      }
      return issue;
    });
  }
  app.get('/api/v1/projects/:projectId/sprints', requireAuth, (req, res) => {
    permissions.assertProject(req, req.params.projectId, 'project:read');
    if (req.query.status) sprintState(req.query.status);
    const rows = db.prepare('SELECT id,status FROM sprints WHERE project_id=? ORDER BY start_date DESC,created_at DESC,id').all(req.params.projectId);
    res.json(ctx.paginate(rows.filter(row => !req.query.status || row.status === req.query.status).map(row => getSprint(ctx, row.id)), req.query));
  });
  app.post('/api/v1/projects/:projectId/sprints', requireAuth, (req, res) => {
    const project = permissions.assertProject(req, req.params.projectId, 'project:write');
    if (project.archived) throw new AppError('CONFLICT', 'Archived projects are read-only', 409);
    const input = sprintInput(req.body);
    validateSprintDates(input.startDate, input.endDate);
    const id = ctx.id(), time = ctx.now();
    db.prepare(`INSERT INTO sprints (id,project_id,name,goal,start_date,end_date,status,created_by,created_at,updated_at)
      VALUES (?,?,?,?,?,?,'planned',?,?,?)`).run(id, project.id, input.name, input.goal, input.startDate, input.endDate, req.user.id, time, time);
    const row = sprintRow(ctx, id), sprint = getSprint(ctx, id);
    emit(req, row, 'created', null, sprint);
    res.status(201).json({ sprint });
  });
  app.get('/api/v1/sprints/:sprintId', requireAuth, (req, res) => {
    permitted(req, req.params.sprintId);
    res.json({ sprint: getSprint(ctx, req.params.sprintId), issues: sprintScope(ctx, req.params.sprintId, { history: req.query.history === 'true' }) });
  });
  app.patch('/api/v1/sprints/:sprintId', requireAuth, (req, res) => {
    const row = permitted(req, req.params.sprintId, 'project:write'); mutable(row);
    const input = sprintInput(req.body, { partial: true });
    if (row.status === 'active' && input.startDate && input.startDate !== row.start_date) throw validation({ startDate: 'An active sprint start date is fixed' });
    validateSprintDates(input.startDate ?? row.start_date, input.endDate ?? row.end_date);
    const before = getSprint(ctx, row.id);
    db.prepare('UPDATE sprints SET name=?,goal=?,start_date=?,end_date=?,updated_at=? WHERE id=?').run(
      input.name ?? row.name, input.goal ?? row.goal, input.startDate ?? row.start_date, input.endDate ?? row.end_date, ctx.now(), row.id
    );
    const sprint = getSprint(ctx, row.id); emit(req, row, 'updated', before, sprint); res.json({ sprint });
  });
  app.delete('/api/v1/sprints/:sprintId', requireAuth, (req, res) => {
    const row = permitted(req, req.params.sprintId, 'project:write');
    if (row.status !== 'planned') throw new AppError('CONFLICT', 'Only a planned sprint may be deleted', 409);
    const before = getSprint(ctx, row.id); db.prepare('DELETE FROM sprints WHERE id=?').run(row.id);
    emit(req, row, 'deleted', before, null); res.json({ ok: true });
  });
  app.post('/api/v1/sprints/:sprintId/start', requireAuth, (req, res) => {
    const row = permitted(req, req.params.sprintId, 'project:write'); fields(req.body ?? {}, []);
    if (row.status !== 'planned') throw new AppError('CONFLICT', 'Only a planned sprint may be started', 409);
    if (db.prepare("SELECT 1 FROM sprints WHERE project_id=? AND status='active'").get(row.project_id)) throw new AppError('CONFLICT', 'This project already has an active sprint', 409);
    const before = getSprint(ctx, row.id), time = ctx.now();
    db.prepare("UPDATE sprints SET status='active',started_at=?,updated_at=? WHERE id=?").run(time, time, row.id);
    const sprint = getSprint(ctx, row.id); emit(req, row, 'started', before, sprint); res.json({ sprint });
  });
  app.post('/api/v1/sprints/:sprintId/issues', requireAuth, (req, res) => {
    const row = permitted(req, req.params.sprintId, 'project:write'); mutable(row);
    const body = fields(req.body, ['issueIds']);
    const ids = uniqueIds(body.issueIds, 'issueIds');
    if (!ids.length) throw validation({ issueIds: 'Select at least one issue' });
    const issues = availableIssues(row, ids), before = getSprint(ctx, row.id);
    ctx.transaction(() => {
      issues.forEach(issue => addSprintIssue(ctx, row.id, issue));
      db.prepare('UPDATE sprints SET updated_at=? WHERE id=?').run(ctx.now(), row.id);
    });
    const sprint = getSprint(ctx, row.id); emit(req, row, 'scope_added', before, { ...sprint, issueIds: ids });
    res.status(201).json({ sprint, issues: sprintScope(ctx, row.id) });
  });
  app.delete('/api/v1/sprints/:sprintId/issues/:issueId', requireAuth, (req, res) => {
    const row = permitted(req, req.params.sprintId, 'project:write'); mutable(row);
    const before = getSprint(ctx, row.id);
    ctx.transaction(() => {
      removeSprintIssue(ctx, row.id, req.params.issueId);
      db.prepare('UPDATE sprints SET updated_at=? WHERE id=?').run(ctx.now(), row.id);
    });
    const sprint = getSprint(ctx, row.id); emit(req, row, 'scope_removed', before, { ...sprint, issueId: req.params.issueId });
    res.json({ sprint, issues: sprintScope(ctx, row.id) });
  });
  app.get('/api/v1/sprints/:sprintId/burndown', requireAuth, (req, res) => {
    permitted(req, req.params.sprintId); res.json(getBurndown(ctx, req.params.sprintId));
  });
  app.post('/api/v1/sprints/:sprintId/complete', requireAuth, (req, res) => {
    const row = permitted(req, req.params.sprintId, 'project:write');
    if (row.status !== 'active') throw new AppError('CONFLICT', 'Only an active sprint may be completed', 409);
    const body = fields(req.body ?? {}, ['carryOverSprintId']);
    const target = body.carryOverSprintId ? permitted(req, text(body.carryOverSprintId, 'carryOverSprintId'), 'project:write') : null;
    if (target && (target.id === row.id || target.project_id !== row.project_id || target.status !== 'planned')) {
      throw validation({ carryOverSprintId: 'Choose another planned sprint in this project' });
    }
    const before = getSprint(ctx, row.id), scope = sprintScope(ctx, row.id);
    const unfinished = scope.filter(item => !item.done && item.issue).map(item => item.issue);
    const result = { completedIssueIds: scope.filter(item => item.done).map(item => item.issueId),
      unfinishedIssueIds: unfinished.map(issue => issue.id), completedPoints: before.scopePoints - before.remainingPoints,
      remainingPoints: before.remainingPoints, carryOverSprintId: target?.id ?? null, carriedIssueIds: target ? unfinished.map(issue => issue.id) : [] };
    const targetBefore = target ? getSprint(ctx, target.id) : null;
    ctx.transaction(() => {
      const time = ctx.now();
      db.prepare("UPDATE sprints SET status='completed',completed_at=?,updated_at=?,result_json=? WHERE id=?").run(time, time, JSON.stringify(result), row.id);
      if (target) {
        availableIssues(target, unfinished.map(issue => issue.id));
        unfinished.forEach(issue => addSprintIssue(ctx, target.id, issue, time));
        db.prepare('UPDATE sprints SET updated_at=? WHERE id=?').run(time, target.id);
      }
    });
    const sprint = getSprint(ctx, row.id); emit(req, row, 'completed', before, sprint);
    if (target) emit(req, target, 'scope_carried', targetBefore, getSprint(ctx, target.id));
    res.json({ sprint, result, carryOverSprint: target ? getSprint(ctx, target.id) : null });
  });
  (ctx.cleanups ??= []).push(observeSprintIssues(ctx));
}

import { fields, text, choice } from '../validate.js';
import { validation } from '../errors.js';
export const SPRINT_STATES = Object.freeze(['planned', 'active', 'completed']);
export function calendarDate(value, field) {
  if (typeof value !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(value)) throw validation({ [field]: 'Use YYYY-MM-DD' });
  const date = new Date(value + 'T00:00:00.000Z');
  if (Number.isNaN(date.valueOf()) || date.toISOString().slice(0, 10) !== value) throw validation({ [field]: 'Use a real calendar date' });
  return value;
}
export function sprintInput(value, { partial = false } = {}) {
  const body = fields(value, ['name', 'goal', 'startDate', 'endDate']);
  const input = {};
  if (!partial || body.name !== undefined) input.name = text(body.name, 'name', { max: 160 });
  if (!partial || body.goal !== undefined) input.goal = text(body.goal ?? '', 'goal', { min: 0, max: 10000 });
  for (const key of ['startDate', 'endDate']) if (!partial || body[key] !== undefined) input[key] = calendarDate(body[key], key);
  if (partial && !Object.keys(input).length) throw validation({ body: 'Provide a sprint field' });
  return input;
}
export function validateSprintDates(startDate, endDate) {
  if (endDate < startDate) throw validation({ endDate: 'End date must be on or after start date' });
  const days = (Date.parse(endDate) - Date.parse(startDate)) / 86400000;
  if (days > 365) throw validation({ endDate: 'A sprint may cover at most 366 calendar days' });
}
export function sprintState(value) {
  return choice(value, 'status', SPRINT_STATES);
}
